/**
 * wAIbi-sabi Zero-API Drafts Ingestion Bridge
 * 
 * Synchronizes article drafts generated by Gemini Spark in Google Sheets / Google Docs
 * directly into Notion Article Production database (d39ea073-cc87-4c25-8a3c-d9f276a59b68).
 * 
 * Operates with ZERO paid API keys:
 * 1. Reads CSV export from Google Sheets 'Drafts' tab.
 * 2. If a Google Doc URL is supplied, fetches the plain text export.
 * 3. Ingests the markdown draft into Notion at `Draft Ready` using NOTION_TOKEN.
 * 4. Runs deterministic preflight assertions to guarantee quality gates.
 * 
 * Usage:
 *   node site/scripts/sync-drafts.mjs [--commit]
 */

import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { api, PRODUCTION_DS, queryAll } from './lib/notion.mjs';

const DEFAULT_SHEET_ID = '1-UcD-C4My_Zp4aH3n-5dB3JQNtDN_MSAK6vTCPt8LY0';
const sheetId = process.env.GOOGLE_SHEET_ID || DEFAULT_SHEET_ID;
const commit = process.argv.includes('--commit');

// Parse CSV with RFC 4180 support
function parseCSV(text) {
  const lines = [];
  let row = [];
  let inQuotes = false;
  let field = '';

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];

    if (c === '"') {
      if (inQuotes && next === '"') {
        field += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (c === ',' && !inQuotes) {
      row.push(field);
      field = '';
    } else if ((c === '\r' || c === '\n') && !inQuotes) {
      if (c === '\r' && next === '\n') i++;
      row.push(field);
      field = '';
      if (row.some((cell) => cell.trim().length > 0)) lines.push(row);
      row = [];
    } else {
      field += c;
    }
  }
  if (field || row.length) {
    row.push(field);
    if (row.some((cell) => cell.trim().length > 0)) lines.push(row);
  }
  return lines;
}

console.log('──────────────────────────────────────────────────────');
console.log('wAIbi-sabi Zero-API Drafts Sync (Google Sheets/Docs → Notion)');
console.log('──────────────────────────────────────────────────────');

const url = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=Drafts`;
console.log(`Fetching Drafts tab: ${url}`);

// Also fetch Radar tab to match reader question and SEO keywords
const radarUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=Radar`;
const radarMap = new Map();
try {
  const radarRes = await fetch(radarUrl);
  if (radarRes.ok) {
    const radarCsv = await radarRes.text();
    const radarRows = parseCSV(radarCsv);
    if (radarRows.length > 1) {
      const rHeaders = radarRows[0].map((h) => h.trim().toLowerCase());
      const rIdx = {
        title: rHeaders.findIndex((h) => h.includes('title') || h.includes('name')),
        question: rHeaders.findIndex((h) => h.includes('question')),
        keywords: rHeaders.findIndex((h) => h.includes('keyword')),
      };
      for (let j = 1; j < radarRows.length; j++) {
        const row = radarRows[j];
        const t = (row[rIdx.title] || '').trim().toLowerCase();
        const q = rIdx.question !== -1 ? (row[rIdx.question] || '').trim() : '';
        const k = rIdx.keywords !== -1 ? (row[rIdx.keywords] || '').trim() : '';
        if (t) radarMap.set(t, { question: q, keywords: k });
      }
    }
  }
} catch (e) {
  // Non-fatal if radar cannot be read
}

let csvText = '';
try {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  csvText = await res.text();
} catch (err) {
  console.warn(`Could not fetch Drafts tab: ${err.message}`);
  process.exit(0);
}

const rows = parseCSV(csvText);
if (rows.length <= 1) {
  console.log('No rows found in Drafts tab. (Ensure tab "Drafts" exists with header row).');
  process.exit(0);
}

const headers = rows[0].map((h) => h.trim().toLowerCase());
// Expected columns: Date, Track, Title, DocUrl (or Markdown), Status
const idx = {
  date: headers.indexOf('date'),
  track: headers.indexOf('track'),
  title: headers.findIndex((h) => h.includes('title') || h.includes('name')),
  docUrl: headers.findIndex((h) => h.includes('doc') || h.includes('url') || h.includes('link')),
  body: headers.findIndex((h) => h.includes('draft') || h.includes('markdown') || h.includes('body') || h.includes('content')),
  status: headers.indexOf('status'),
};

if (idx.title === -1) {
  console.log('Tab does not appear to be a Drafts table (missing Title header).');
  console.log('Headers found:', headers.join(', '));
  process.exit(0);
}

// Fetch existing Notion Production articles to avoid duplicates
console.log('Fetching existing Notion Production articles...');
const existingNotionRows = await queryAll(PRODUCTION_DS);
const existingTitles = new Set(
  existingNotionRows.map((r) =>
    (r.properties.Name?.title?.[0]?.plain_text || '').trim().toLowerCase()
  )
);

const pendingDrafts = [];

for (let i = 1; i < rows.length; i++) {
  const r = rows[i];
  const title = (r[idx.title] ?? '').trim();
  if (!title) continue;

  if (existingTitles.has(title.toLowerCase())) {
    continue; // Already in Notion
  }

  const track = (r[idx.track] ?? 'Technical').trim() || 'Technical';
  const docUrl = idx.docUrl !== -1 ? (r[idx.docUrl] ?? '').trim() : '';
  const bodyText = idx.body !== -1 ? (r[idx.body] ?? '').trim() : '';
  const status = idx.status !== -1 ? (r[idx.status] ?? 'Ready').trim() : 'Ready';

  pendingDrafts.push({ title, track, docUrl, bodyText, status });
}

console.log(`Found ${pendingDrafts.length} pending draft(s) in Google Sheets.`);

if (pendingDrafts.length === 0) {
  console.log('All drafts in Google Sheet are already filed in Notion Article Production.');
  process.exit(0);
}

for (const draft of pendingDrafts) {
  console.log(`\n• Processing: "${draft.title}" [${draft.track}]`);

  let markdown = draft.bodyText;

  // If a Google Doc URL is supplied, fetch the plain text export directly
  if (!markdown && draft.docUrl) {
    const docIdMatch = draft.docUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (docIdMatch) {
      const docId = docIdMatch[1];
      const exportUrl = `https://docs.google.com/document/d/${docId}/export?format=txt`;
      console.log(`  Fetching Google Doc export: ${exportUrl}`);
      try {
        const docRes = await fetch(exportUrl);
        if (docRes.ok) {
          markdown = await docRes.text();
          console.log(`  ✓ Retrieved ${markdown.length} characters from Google Doc.`);
        } else {
          console.warn(`  ✗ Failed to fetch Google Doc: HTTP ${docRes.status}`);
        }
      } catch (err) {
        console.warn(`  ✗ Error fetching Google Doc: ${err.message}`);
      }
    }
  }

  if (!markdown) {
    console.warn(`  ✗ No markdown content or valid Google Doc found for "${draft.title}". Skipping.`);
    continue;
  }

  // Resolve Reader Question & Keywords from Radar metadata if available
  let question = '';
  let keywords = '';
  const cleanTitle = draft.title.toLowerCase();
  for (const [rTitle, rData] of radarMap.entries()) {
    if (cleanTitle.includes(rTitle.slice(0, 20)) || rTitle.includes(cleanTitle.slice(0, 20))) {
      question = rData.question;
      keywords = rData.keywords;
      break;
    }
  }

  // Prepend frontmatter so import-draft extracts all metadata accurately
  const cleanQ = question ? `question: "${question.replace(/["\r\n]/g, '')}"\n` : '';
  const cleanK = keywords ? `keywords: "${keywords.replace(/["\r\n]/g, '')}"\n` : '';
  const frontmatter = `---\ntitle: "${draft.title.replace(/["\r\n]/g, '')}"\ntrack: "${draft.track}"\n${cleanQ}${cleanK}---\n\n`;

  // Save to temporary scratch draft file
  const safeSlug = draft.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
  const tempPath = resolve('drafts', `temp-${safeSlug}.md`);
  writeFileSync(tempPath, frontmatter + markdown, 'utf8');

  // Use import-draft.mjs to ingest into Notion
  console.log(`  Ingesting draft via import-draft.mjs...`);
  const args = ['site/scripts/import-draft.mjs', tempPath];
  if (commit) args.push('--commit');

  const proc = spawnSync('node', args, { encoding: 'utf8' });
  console.log(proc.stdout);
  if (proc.status !== 0) {
    console.error(proc.stderr);
  }
}

console.log('\nDraft sync sweep finished.');
